n=26
E={}
for i in range(n):
 for j in range(i+1,n):
  E[(i,j)]=z3.Bool(f'e_{i}_{j}')

def e(i,j):
 if i>j: i,j=j,i
 return E[(i,j)]

s=z3.Solver()
# exact degree 3
for v in range(n):
 inc=[e(v,u) for u in range(n) if u!=v]
